        "title",
        "text",
        "sender"
      ]
    },
    "NotifyJob": {
      "description": "a job to deliver message",
      "type": "object",
      "properties": {
        "guid": {
          "description": "global identifier",
          "type": "string",
          "format": "uuid"
        },
        "message": {
          "$ref": "#/definitions/Message",
          "example": "bar-chart"
        },
        "type": {
          "description": "how should the message be delivered",
          "type": "string",
          "enum": [
            "email",
            "sms",
            "webhook"
          ]
        },
        "receiver": {
          "description": "who should receive the message",
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "times": {
          "type": "object",
